diy:nshanlang.code:
{
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event, player) {
      return player.countCards("h") > 0 && game.hasPlayer((current) => player != current && player.canCompare(current));
    },
    async cost(event, trigger, player) {
      const goon = player.hasCard(function(card) {
        return get.value(card) <= 7;
      }, "h");
      event.result = await player.chooseTarget([1, 3], get.prompt(event.skill), "和至多三名角色进行拼点", function(card, player2, target) {
        return target != player2 && player2.canCompare(target);
      }).set("ai", function(target) {
        if (!_status.event.goon) {
          return false;
        }
        var att = get.attitude(_status.event.player, target);
        if (att >= 0) {
          return 0;
        }
        if (target.hasSkillTag("noh")) {
          att /= 3;
        }
        return -att / Math.sqrt(target.countCards("h"));
      }).set("goon", goon).forResult();
    },
    async content(event, trigger, player) {
      const { targets } = event;
      let result2;
      event.max_num = 0;
      targets.sortBySeat();
      const next = player.chooseToCompare(targets);
      next.callback = lib.skill.nshanlang.callback;
      await next;
      if (!event.target) {
        return;
      }
      const target = event.target;
      result2 = await player.chooseBool("是否令" + get.translation(target) + "获得一张牌？").set("goon", get.attitude(player, target) > 0).set("ai", () => _status.event.goon).forResult();
      if (result2.bool) {
        const card = get.cardPile2((card2) => {
          return !lib.skill.nsxingyun.getSixiang(card2);
        });
        if (card) {
          await target.gain(card, "gain2");
        }
      }
    },
    async callback(event, trigger, player) {
      const { target } = event;
      var list = [
        [player, event.num1],
        [target, event.num2]
      ], evt = event.getParent(2);
      for (var i of list) {
        if (i[1] > evt.max_num) {
          evt.max_num = i[1];
          evt.target = i[0];
        } else if (evt.target && i[1] == evt.max_num && i[0] != evt.target) {
          delete evt.target;
        }
      }
    }
  }

