{
    audio: 2,
    trigger: { source: "damageBegin2" },
    preHidden: true,
    filter(event2, player2) {
      if (_status.currentPhase != player2) {
        return false;
      }
      if (!_status.event.getParent("phaseUse")) {
        return false;
      }
      if (event2.card && (event2.card.name == "sha" || event2.card.name == "juedou") && event2.getParent().name == event2.card.name) {
        if (get.mode() == "guozhan") {
          return (event2.player.identity != "qun" || player2.identity == "ye") && !event2.player.isUnseen() && event2.player.hasViceCharacter();
        } else {
          var info = lib.character[event2.player.name];
          if (!info) {
            return false;
          }
          var skills2 = event2.player.getSkills();
          for (var i = 0; i < info[3].length; i++) {
            if (lib.skill[info[3][i]].fixed) {
              continue;
            }
            if (skills2.includes(info[3][i])) {
              return true;
            }
          }
        }
      }
      return false;
    },
    logTarget: "player",
    check(event2, player2) {
      if (get.mode() == "guozhan") {
        if (!event2.player.isUnseen(1) && get.guozhanRank(event2.player.name2, event2.player) < 4) {
          return false;
        }
      }
      if (event2.player.hasSkill("subplayer")) {
        return false;
      }
      if (get.attitude(player2, event2.player) < 0) {
        if (event2.player.hp == 1 && event2.player.countCards("e") < 2 && event2.player.name2 != "gz_pangtong") {
          return false;
        }
        return true;
      }
      return false;
    },
    async content(event2, trigger2, player2) {
      trigger2.cancel();
      let result;
      if (trigger2.player.countCards("e")) {
        result = await trigger2.player.chooseControl(function(event3, player3) {
          if (get.mode() == "guozhan" && get.guozhanRank(player3.name2, player3) < 4) {
            return 1;
          }
          if (player3.hp == 1) {
            return 1;
          }
          if (player3.hp == 2 && player3.countCards("e") >= 2) {
            return 1;
          }
          return 0;
        }).set("choiceList", ["弃置装备区内的所有牌并失去1点体力", get.mode() == "guozhan" ? "移除副将牌" : "随机移除武将牌上的一个技能"]).forResult();
      } else {
        event2._result = { index: 1 };
        result = event2._result;
      }
      if (result.index == 1) {
        if (get.mode() != "guozhan") {
          const info = lib.character[trigger2.player.name];
          const skills2 = trigger2.player.getSkills();
          const list = [];
          for (let i = 0; i < info[3].length; i++) {
            if (lib.skill[info[3][i]].fixed) {
              continue;
            }
            if (skills2.includes(info[3][i])) {
              list.push(info[3][i]);
            }
          }
          if (list.length) {
            const skill = list.randomGet();
            await trigger2.player.removeSkills(skill);
          }
        } else {
          await trigger2.player.removeCharacter(1);
        }
      } else {
        await trigger2.player.discard(trigger2.player.getCards("e"));
        await trigger2.player.loseHp();
      }
    }
  }

